CONCEPTS = [
# ---- c1 systems
C("c1","Linear equation | Phương trình tuyến tính","$a_1x_1+\\dots+a_nx_n=b$ with constant coefficients; each unknown to the first power, no products or functions of unknowns. | $a_1x_1+\\dots+a_nx_n=b$ với hệ số hằng; mỗi ẩn bậc nhất, không có tích hay hàm của ẩn.","$\\cos 3\\cdot x$ is linear; $xy$, $1/x$, $\\sin x$ are not. | $\\cos 3\\cdot x$ tuyến tính; $xy$, $1/x$, $\\sin x$ thì không.",["Pick the linear equation among five | Chọn phương trình tuyến tính trong năm phương trình","Which parameter value makes an equation linear | Giá trị tham số nào làm phương trình tuyến tính"],["Linear equations"],"linear nonlinear coefficient"),
C("c1","Augmented matrix and row operations | Ma trận mở rộng và phép biến đổi hàng","$[A\\mid b]$ stores a system; the three row operations (swap, scale, add a multiple) do not change the solution set. | $[A\\mid b]$ lưu một hệ; ba phép biến đổi hàng (đổi chỗ, nhân, cộng bội) không đổi tập nghiệm.","Echelon form: staircase of pivots; RREF: pivots 1 with zeros above and below. | Dạng bậc thang: các pivot hình bậc thang; RREF: pivot bằng 1, trên dưới đều 0.",["Write the augmented matrix after given operations | Viết ma trận mở rộng sau các phép biến đổi cho trước","Count the operations / find the pivot columns | Đếm phép biến đổi / tìm cột pivot"],["Row operations","Reading an RREF"],"gauss jordan echelon rref pivot"),
C("c1","Solution sets: none, unique, infinitely many | Tập nghiệm: vô nghiệm, duy nhất, vô số","Compare $\\operatorname{rank}A$ and $\\operatorname{rank}[A|b]$: smaller ⇒ none; equal $=n$ ⇒ unique; equal $<n$ ⇒ infinite. | So sánh $\\operatorname{rank}A$ và $\\operatorname{rank}[A|b]$: nhỏ hơn ⇒ vô nghiệm; bằng $=n$ ⇒ duy nhất; bằng $<n$ ⇒ vô số.","Free variables $=n-\\operatorname{rank}A$. | Số biến tự do $=n-\\operatorname{rank}A$.",["Classify by a parameter (determinant, then test each root) | Phân loại theo tham số (định thức rồi thử từng nghiệm)","Describe the solution set with free parameters | Mô tả tập nghiệm bằng tham số tự do","Count parameter values giving no solution | Đếm số giá trị tham số làm hệ vô nghiệm"],["Solution sets","Solving systems","Systems with a parameter"],"consistent inconsistent parameter free variable",False),
C("c1","Rank | Hạng của ma trận","Number of pivots after row reduction = dimension of the row space = dimension of the column space. | Số pivot sau khi rút gọn = số chiều không gian hàng = số chiều không gian cột.","$\\operatorname{rank}A\\le\\min(m,n)$; $\\operatorname{rank}A+\\operatorname{nullity}A=n$ (columns). | $\\operatorname{rank}A\\le\\min(m,n)$; $\\operatorname{rank}A+\\operatorname{nullity}A=n$ (số cột).",["Compute the rank of a $4\\times5$ matrix | Tính hạng ma trận $4\\times5$","Rank as a function of a parameter | Hạng theo tham số","Use rank to decide solvability | Dùng hạng để xét nghiệm"],["Rank"],"pivot rank nullity",True),
# ---- c2 matrices
C("c2","Matrix product and sizes | Tích ma trận và kích thước","$(m\\times n)(n\\times p)=m\\times p$; inner sizes must match; $AB\\ne BA$ in general. | $(m\\times n)(n\\times p)=m\\times p$; hai số trong phải bằng nhau; nói chung $AB\\ne BA$.","$(AB)^T=B^TA^T$; $\\operatorname{tr}(AB)=\\operatorname{tr}(BA)$. | $(AB)^T=B^TA^T$; $\\operatorname{tr}(AB)=\\operatorname{tr}(BA)$.",["Which products exist and what size | Tích nào tồn tại, cỡ bao nhiêu","Find $AB$ and $BA$ and compare | Tính $AB$, $BA$ rồi so sánh","Commuting matrices (parameters) | Ma trận giao hoán (có tham số)"],["Sizes of products","Matrix products","Algebra of matrices","Transpose","Trace","Powers"],"multiply product commute transpose trace"),
C("c2","Inverse of a matrix | Ma trận nghịch đảo","$A^{-1}$ with $AA^{-1}=A^{-1}A=I$; exists iff $\\det A\\ne0$ iff rank $=n$. | $A^{-1}$ với $AA^{-1}=A^{-1}A=I$; tồn tại iff $\\det A\\ne0$ iff hạng $=n$.","$2\\times2$: $\\frac1{ad-bc}\\begin{bmatrix}d&-b\\\\-c&a\\end{bmatrix}$; $(AB)^{-1}=B^{-1}A^{-1}$; $(cA)^{-1}=\\frac1cA^{-1}$. | Cỡ $2\\times2$: $\\frac1{ad-bc}\\begin{bmatrix}d&-b\\\\-c&a\\end{bmatrix}$; $(AB)^{-1}=B^{-1}A^{-1}$; $(cA)^{-1}=\\frac1cA^{-1}$.",["Invert by Gauss–Jordan $[A|I]$ | Nghịch đảo bằng Gauss–Jordan $[A|I]$","Recover $A$ from $(3A)^{-1}$ or from a matrix polynomial | Tìm $A$ từ $(3A)^{-1}$ hoặc từ đa thức ma trận","Solve $AX=B$ vs $XA=B$ | Giải $AX=B$ và $XA=B$"],["Inverse (Gauss–Jordan)","Inverse (2×2 formula)","Inverse (special forms)","Invertibility","Properties","Determinant rules"],"inverse invertible nonsingular singular"),
C("c2","Special matrices | Ma trận đặc biệt","Diagonal, triangular, symmetric ($A^T=A$), skew ($A^T=-A$), identity, zero, idempotent, nilpotent. | Chéo, tam giác, đối xứng ($A^T=A$), phản đối xứng ($A^T=-A$), đơn vị, không, lũy đẳng, lũy linh.","Diagonal powers act entrywise; $A+A^T$ is symmetric, $A-A^T$ skew. | Lũy thừa ma trận chéo tác động từng phần tử; $A+A^T$ đối xứng, $A-A^T$ phản đối xứng.",["Name the type of a given matrix | Gọi tên loại ma trận","Powers of a diagonal / nilpotent matrix | Lũy thừa ma trận chéo / lũy linh"],["Powers","Properties"],"diagonal triangular symmetric skew nilpotent idempotent"),
# ---- c3 determinants
C("c3","Determinant | Định thức","Number $\\det A$ with $\\det A\\ne0$ iff $A$ invertible; row swap flips sign, scaling a row scales $\\det$, adding a multiple of a row changes nothing. | Số $\\det A$ với $\\det A\\ne0$ iff $A$ khả nghịch; đổi hai hàng đổi dấu, nhân một hàng nhân $\\det$, cộng bội của hàng không đổi.","$\\det(AB)=\\det A\\det B$; $\\det(cA)=c^n\\det A$; $\\det A^T=\\det A$. | $\\det(AB)=\\det A\\det B$; $\\det(cA)=c^n\\det A$; $\\det A^T=\\det A$.",["Compute a $4\\times4$ determinant with parameters | Tính định thức $4\\times4$ có tham số","Use properties instead of expanding | Dùng tính chất thay vì khai triển","Parameter making the matrix singular | Tham số làm ma trận suy biến"],["Computing determinants","Properties of det","Invertibility"],"det determinant cofactor expansion"),
C("c3","Adjugate (adjoint) | Ma trận phụ hợp adj(A)","$\\operatorname{adj}A=C^T$ where $C$ is the cofactor matrix; $A\\operatorname{adj}A=\\det A\\cdot I$. | $\\operatorname{adj}A=C^T$ với $C$ là ma trận phần phụ đại số; $A\\operatorname{adj}A=\\det A\\cdot I$.","$A^{-1}=\\frac1{\\det A}\\operatorname{adj}A$; $\\det(\\operatorname{adj}A)=(\\det A)^{n-1}$; $\\operatorname{adj}(AB)=\\operatorname{adj}B\\operatorname{adj}A$. | $A^{-1}=\\frac1{\\det A}\\operatorname{adj}A$; $\\det(\\operatorname{adj}A)=(\\det A)^{n-1}$; $\\operatorname{adj}(AB)=\\operatorname{adj}B\\operatorname{adj}A$.",["Compute $\\operatorname{adj}A$ for a $3\\times3$ matrix | Tính $\\operatorname{adj}A$ cho ma trận $3\\times3$","Given $\\operatorname{adj}A$ find $A^{-1}$ or $\\det A$ | Cho $\\operatorname{adj}A$ tìm $A^{-1}$ hoặc $\\det A$","Entry $(i,j)$ of the inverse via cofactors | Phần tử $(i,j)$ của nghịch đảo qua phần phụ đại số"],["Adjugate"],"adjoint adjugate cofactor adj",True),
C("c3","Cramer's rule | Quy tắc Cramer","For $\\det A\\ne0$: $x_i=\\det A_i/\\det A$ where $A_i$ has column $i$ replaced by $b$. | Với $\\det A\\ne0$: $x_i=\\det A_i/\\det A$ trong đó $A_i$ thay cột $i$ bằng $b$.","Only for square systems with unique solution; useful for a single unknown. | Chỉ cho hệ vuông có nghiệm duy nhất; tiện khi chỉ cần một ẩn.",["Find one unknown without solving the system | Tìm một ẩn mà không giải cả hệ","Cramer with a parameter | Cramer có tham số"],["Cramer's rule"],"cramer unknown replace column"),
# ---- c4 vector spaces
C("c4","Vector space axioms | Tiên đề không gian vectơ","A set with addition and scalar multiplication satisfying 10 axioms (closure, zero, negatives, commutativity, associativity, distributivity, $1\\cdot v=v$). | Tập có phép cộng và nhân vô hướng thoả 10 tiên đề (đóng, vectơ không, đối, giao hoán, kết hợp, phân phối, $1\\cdot v=v$).","To disprove: exhibit one failing axiom with numbers. | Để bác bỏ: chỉ ra một tiên đề sai bằng số cụ thể.",["Which axiom fails for a strange addition | Tiên đề nào sai với phép cộng lạ","Is the set of functions/polynomials/matrices with a condition a vector space | Tập hàm/đa thức/ma trận có điều kiện có là không gian vectơ không"],["Vector space axioms","Vector arithmetic"],"axiom closure zero vector"),
C("c4","Subspace | Không gian con","$W\\subseteq V$ is a subspace iff $\\mathbf0\\in W$ and $W$ is closed under addition and scalar multiplication. | $W\\subseteq V$ là không gian con iff $\\mathbf0\\in W$ và $W$ đóng với phép cộng và nhân vô hướng.","Inequalities, non-homogeneous equations and unions of lines usually fail. | Bất đẳng thức, phương trình không thuần nhất và hợp của các đường thẳng thường không phải không gian con.",["Test sets defined by equations or inequalities | Kiểm tra tập xác định bằng phương trình/bất phương trình","Subspaces of $P_n$, $M_{2\\times2}$, functions | Không gian con của $P_n$, $M_{2\\times2}$, hàm số","Dimension of an intersection / sum | Số chiều của giao / tổng"],["Subspaces"],"subspace closed zero",True),
C("c4","Linear combination and span | Tổ hợp tuyến tính và không gian sinh","$\\operatorname{span}\\{v_1..v_k\\}$ = all $c_1v_1+\\dots+c_kv_k$; it is the smallest subspace containing the $v_i$. | $\\operatorname{span}\\{v_1..v_k\\}$ = mọi $c_1v_1+\\dots+c_kv_k$; là không gian con nhỏ nhất chứa các $v_i$.","$w\\in\\operatorname{span}$ iff $[v_1\\dots v_k\\mid w]$ is consistent; $\\{v_i\\}$ spans $\\mathbb R^n$ iff rank $=n$. | $w\\in\\operatorname{span}$ iff $[v_1\\dots v_k\\mid w]$ có nghiệm; $\\{v_i\\}$ sinh $\\mathbb R^n$ iff hạng $=n$.",["Is $w$ in the span (solve a system) | $w$ có thuộc không gian sinh không (giải hệ)","For which parameter does the set span $\\mathbb R^3$ | Tham số nào làm tập sinh $\\mathbb R^3$","Describe the span as a plane / equation | Mô tả không gian sinh bằng phương trình mặt phẳng","Span of polynomials or matrices | Không gian sinh của đa thức hoặc ma trận"],["Linear combinations","Span, independence, basis"],"span spanning generate combination",True),
C("c4","Linear independence | Độc lập tuyến tính","$c_1v_1+\\dots+c_kv_k=0$ only for all $c_i=0$. Dependent iff one vector is a combination of the others. | $c_1v_1+\\dots+c_kv_k=0$ chỉ khi mọi $c_i=0$. Phụ thuộc iff một vectơ là tổ hợp của các vectơ khác.","$n$ vectors in $\\mathbb R^n$: independent iff $\\det\\ne0$; more than $n$ vectors in $\\mathbb R^n$ are dependent. | $n$ vectơ trong $\\mathbb R^n$: độc lập iff $\\det\\ne0$; hơn $n$ vectơ trong $\\mathbb R^n$ thì phụ thuộc.",["Which set is dependent | Tập nào phụ thuộc","Parameter for dependence | Tham số làm phụ thuộc","True/false about rank and independence | Đúng/sai về hạng và độc lập"],["Span, independence, basis"],"independent dependent",True),
C("c4","Basis and dimension | Cơ sở và số chiều","A basis is an independent spanning set; $\\dim V$ = number of vectors in any basis. | Cơ sở là tập sinh độc lập; $\\dim V$ = số vectơ của một cơ sở bất kỳ.","$\\dim\\mathbb R^n=n$, $\\dim P_n=n+1$, $\\dim M_{m\\times n}=mn$, $\\dim\\{0\\}=0$ (basis $\\emptyset$). | $\\dim\\mathbb R^n=n$, $\\dim P_n=n+1$, $\\dim M_{m\\times n}=mn$, $\\dim\\{0\\}=0$ (cơ sở $\\emptyset$).",["Find a basis of a span / solution space | Tìm cơ sở của không gian sinh / không gian nghiệm","Extend an independent set to a basis | Mở rộng tập độc lập thành cơ sở","Dimension of a subspace defined by conditions | Số chiều của không gian con xác định bởi điều kiện"],["Span, independence, basis","Null space and rank"],"basis dimension",True),
C("c4","Row space, column space, null space | Không gian hàng, cột, nghiệm","$\\operatorname{row}A$ and $\\operatorname{col}A$ both have dimension rank; $\\operatorname{null}A=\\{x:Ax=0\\}$ has dimension $n-\\operatorname{rank}$. | $\\operatorname{row}A$ và $\\operatorname{col}A$ đều có số chiều bằng hạng; $\\operatorname{null}A=\\{x:Ax=0\\}$ có số chiều $n-$ hạng.","Basis of row space: nonzero rows of the echelon form; of column space: the <i>original</i> pivot columns. | Cơ sở không gian hàng: các hàng khác 0 của dạng bậc thang; không gian cột: các cột pivot <i>gốc</i>.",["Basis of the row / column / null space | Cơ sở không gian hàng / cột / nghiệm","Which of the four fundamental subspaces contains a vector | Vectơ thuộc không gian con cơ bản nào","Rank–nullity bookkeeping | Tính toán hạng–số chiều nhân"],["Null space and rank"],"row space column space null space kernel",True),
C("c4","Coordinates and change of basis | Tọa độ và đổi cơ sở","$[x]_B$ = coefficients of $x$ in basis $B$; $P_{B\\to B'}=(B')^{-1}B$ in matrix form. | $[x]_B$ = hệ số của $x$ theo cơ sở $B$; dạng ma trận $P_{B\\to B'}=(B')^{-1}B$.","To change: go to the standard basis first, then to the new one. | Để đổi: về cơ sở chuẩn trước rồi sang cơ sở mới.",["Find $[x]_{B'}$ from $[x]_B$ | Tìm $[x]_{B'}$ từ $[x]_B$","Transition matrix between two bases | Ma trận chuyển cơ sở","Coordinates of a polynomial/matrix | Tọa độ của đa thức/ma trận"],["Coordinates and change of basis"],"coordinates transition basis change"),
# ---- c5 inner product
C("c5","Inner product, norm, angle | Tích vô hướng, chuẩn, góc","$\\langle u,v\\rangle$ symmetric, linear, positive; $\\|u\\|=\\sqrt{\\langle u,u\\rangle}$, $\\cos\\theta=\\frac{\\langle u,v\\rangle}{\\|u\\|\\|v\\|}$. | $\\langle u,v\\rangle$ đối xứng, tuyến tính, dương; $\\|u\\|=\\sqrt{\\langle u,u\\rangle}$, $\\cos\\theta=\\frac{\\langle u,v\\rangle}{\\|u\\|\\|v\\|}$.","Cauchy–Schwarz $|\\langle u,v\\rangle|\\le\\|u\\|\\|v\\|$; triangle inequality. | Cauchy–Schwarz $|\\langle u,v\\rangle|\\le\\|u\\|\\|v\\|$; bất đẳng thức tam giác.",["Norm/angle in $\\mathbb R^n$ or in function spaces | Chuẩn/góc trong $\\mathbb R^n$ hoặc không gian hàm","Is a formula an inner product | Công thức có là tích vô hướng không"],["Norm, distance, angle","Inner products","Function spaces"],"inner product dot norm angle orthogonal"),
C("c5","Orthogonal projection and complement | Hình chiếu trực giao và phần bù","$\\operatorname{proj}_uv=\\frac{\\langle v,u\\rangle}{\\langle u,u\\rangle}u$; $W^\\perp$ = vectors orthogonal to all of $W$, $\\dim W+\\dim W^\\perp=n$. | $\\operatorname{proj}_uv=\\frac{\\langle v,u\\rangle}{\\langle u,u\\rangle}u$; $W^\\perp$ = vectơ trực giao với mọi vectơ của $W$, $\\dim W+\\dim W^\\perp=n$.","$(\\operatorname{row}A)^\\perp=\\operatorname{null}A$. | $(\\operatorname{row}A)^\\perp=\\operatorname{null}A$.",["Project a vector on a line / subspace | Chiếu vectơ lên đường thẳng / không gian con","Find a basis of $W^\\perp$ | Tìm cơ sở của $W^\\perp$"],["Projections","Orthogonal complements"],"projection complement perpendicular"),
C("c5","Gram–Schmidt and least squares | Gram–Schmidt và bình phương tối thiểu","Orthonormalise a basis step by step; least squares solves $A^TAx=A^Tb$. | Trực chuẩn hoá một cơ sở từng bước; bình phương tối thiểu giải $A^TAx=A^Tb$.","$u_k=v_k-\\sum\\operatorname{proj}_{u_j}v_k$, then normalise. | $u_k=v_k-\\sum\\operatorname{proj}_{u_j}v_k$, rồi chuẩn hoá.",["Orthonormal basis from a given basis | Cơ sở trực chuẩn từ cơ sở cho trước","Best-fit line through points | Đường thẳng khớp nhất qua các điểm"],["Gram–Schmidt","Least squares"],"gram schmidt orthonormal least squares"),
# ---- c6 linear maps
C("c6","Linear transformation | Ánh xạ tuyến tính","$T(u+v)=T(u)+T(v)$ and $T(cu)=cT(u)$; equivalently $T(\\mathbf0)=\\mathbf0$ and preserves combinations. | $T(u+v)=T(u)+T(v)$ và $T(cu)=cT(u)$; tương đương $T(\\mathbf0)=\\mathbf0$ và bảo toàn tổ hợp.","Standard matrix: columns are $T(e_1),\\dots,T(e_n)$. | Ma trận chuẩn: các cột là $T(e_1),\\dots,T(e_n)$.",["Is the map linear (check both rules or find a counterexample) | Ánh xạ có tuyến tính không","Find the standard matrix | Tìm ma trận chuẩn","Compute an image or a preimage | Tính ảnh hoặc tạo ảnh"],["Linear or not","Standard matrix","Image and preimage","Extension: Jacobian matrix"],"linear map transformation standard matrix"),
C("c6","Kernel, range and rank–nullity | Nhân, ảnh và định lý hạng–số chiều nhân","$\\ker T=\\{v:T(v)=0\\}$, $\\operatorname{range}T=\\{T(v)\\}$; $\\dim\\ker+\\dim\\operatorname{range}=\\dim V$. | $\\ker T=\\{v:T(v)=0\\}$, $\\operatorname{range}T=\\{T(v)\\}$; $\\dim\\ker+\\dim\\operatorname{range}=\\dim V$.","One-to-one iff $\\ker=\\{0\\}$; onto iff range $=W$; isomorphism iff both. | Đơn ánh iff $\\ker=\\{0\\}$; toàn ánh iff ảnh $=W$; đẳng cấu iff cả hai.",["Basis of kernel and range | Cơ sở của nhân và ảnh","Decide one-to-one / onto from dimensions | Xét đơn ánh/toàn ánh từ số chiều","Invertibility of $T$ | Tính khả nghịch của $T$"],["Kernel, range, rank–nullity","One-to-one and onto","Invertible maps","Composition"],"kernel range image nullity one-to-one onto isomorphism",True),
C("c6","Matrix of a map relative to bases; similarity | Ma trận của ánh xạ theo cơ sở; đồng dạng","$[T]_{B,B'}$; $A$ and $B$ are similar if $B=P^{-1}AP$; similar matrices share det, trace, eigenvalues. | $[T]_{B,B'}$; $A$ và $B$ đồng dạng nếu $B=P^{-1}AP$; ma trận đồng dạng cùng det, vết, trị riêng.","$[T]_{B'}=P^{-1}[T]_BP$ with $P$ the transition matrix. | $[T]_{B'}=P^{-1}[T]_BP$ với $P$ là ma trận chuyển cơ sở.",["Matrix of $T$ in a non-standard basis | Ma trận của $T$ trong cơ sở không chuẩn","Show two matrices are (not) similar | Chứng minh hai ma trận (không) đồng dạng"],["Matrix relative to bases","Similar matrices"],"similar similarity change of basis"),
# ---- c7 eigen
C("c7","Eigenvalues and eigenvectors | Trị riêng và vectơ riêng","$Av=\\lambda v$ with $v\\ne0$; $\\lambda$ is a root of $\\det(A-\\lambda I)=0$. | $Av=\\lambda v$ với $v\\ne0$; $\\lambda$ là nghiệm của $\\det(A-\\lambda I)=0$.","$\\operatorname{tr}A=\\sum\\lambda_i$, $\\det A=\\prod\\lambda_i$; triangular matrix: eigenvalues are the diagonal entries. | $\\operatorname{tr}A=\\sum\\lambda_i$, $\\det A=\\prod\\lambda_i$; ma trận tam giác: trị riêng là các phần tử đường chéo.",["Eigenvalues of a $3\\times3$ matrix | Trị riêng của ma trận $3\\times3$","Eigenvalues of $A^2$, $A^{-1}$, $A+cI$ | Trị riêng của $A^2$, $A^{-1}$, $A+cI$","Find $k$ from a given eigenvalue | Tìm $k$ từ trị riêng cho trước"],["Eigenvalues","Eigenvectors"],"eigenvalue eigenvector characteristic polynomial"),
C("c7","Diagonalization | Chéo hoá","$A=PDP^{-1}$ iff $A$ has $n$ independent eigenvectors; then $A^k=PD^kP^{-1}$. | $A=PDP^{-1}$ iff $A$ có $n$ vectơ riêng độc lập; khi đó $A^k=PD^kP^{-1}$.","Distinct eigenvalues ⇒ diagonalizable; check geometric = algebraic multiplicity otherwise. | Trị riêng phân biệt ⇒ chéo hoá được; ngược lại so bội hình học với bội đại số.",["Is $A$ diagonalizable (parameter) | $A$ có chéo hoá được không (tham số)","Compute $A^{10}$ via $PD^{10}P^{-1}$ | Tính $A^{10}$ bằng $PD^{10}P^{-1}$"],["Diagonalization","Powers via diagonalization"],"diagonalize diagonalizable power"),
C("c7","Symmetric and orthogonal matrices | Ma trận đối xứng và trực giao","Symmetric real matrices have real eigenvalues and orthogonal eigenvectors: $A=QDQ^T$; $Q$ orthogonal means $Q^TQ=I$. | Ma trận thực đối xứng có trị riêng thực và vectơ riêng trực giao: $A=QDQ^T$; $Q$ trực giao nghĩa là $Q^TQ=I$.","Orthogonal $Q$ preserves length and angle, $\\det Q=\\pm1$. | $Q$ trực giao bảo toàn độ dài và góc, $\\det Q=\\pm1$.",["Orthogonally diagonalise a symmetric matrix | Chéo hoá trực giao ma trận đối xứng","Recognise an orthogonal matrix | Nhận biết ma trận trực giao"],["Orthogonal matrices"],"symmetric orthogonal spectral"),
]
